var UUIDGenerator = function() {
    this.ip = this.ipToInt(this.getIPAddress());
    this.pid = process.pid;
    this.seq = 0;
};

const pad = ["", "0", "00", "000", "0000", "00000", "000000", "0000000", "00000000"];
const REG = /^(\d{1,2}|1\d\d|2[0-4]\d|25[0-5])\.(\d{1,2}|1\d\d|2[0-4]\d|25[0-5])\.(\d{1,2}|1\d\d|2[0-4]\d|25[0-5])\.(\d{1,2}|1\d\d|2[0-4]\d|25[0-5])$/;

UUIDGenerator.prototype.getIPAddress = function() {
    var interfaces = require('os').networkInterfaces();
    for (var devName in interfaces) {
        var iface = interfaces[devName];
        for (var i = 0; i < iface.length; i++) {
            var alias = iface[i];
            if (alias.family === 'IPv4' && alias.address !== '127.0.0.1' && !alias.internal) {
                return alias.address;
            }
        }
    }
};

UUIDGenerator.prototype.ipToInt = function(ip) {
    var xH = "",
        result = REG.exec(ip);
    if (!result) return -1;
    return (parseInt(result[1]) << 24 |
        parseInt(result[2]) << 16 |
        parseInt(result[3]) << 8 |
        parseInt(result[4]));
};

UUIDGenerator.prototype.nowTimestamp = function() {
    return parseInt(Date.now() / 1000);
};

/////////////////////////////////////////
UUIDGenerator.prototype.init = function(ip) {
    if (ip && ip != "") {
        this.ip = ip;
    }

    this.ip = this.ipToInt(ip);
};

UUIDGenerator.prototype.intToHexstr = function(i) {
    i = Math.abs(parseInt(i))
    var str = i.toString(16);
    if (str.length < 8) {
        str = pad[8 - str.length] + str;
    }
    return str;
}

UUIDGenerator.prototype.genID = function() {
    if (!this.ip) {
        return "";
    }
    this.seq = this.seq + 1;
    return this.intToHexstr(this.ip) + this.intToHexstr(this.pid) + this.intToHexstr(this.nowTimestamp()) + this.intToHexstr(this.seq);
}

var instance = new UUIDGenerator();
module.exports = instance;
